import{_ as t,o as s,c as r,a0 as a}from"./chunks/framework.D4fUSYzX.js";const m=JSON.parse('{"title":"ADR 0047: The pull request state judgment reads the source at settle time","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0047-the-pull-request-state-judgment-reads-the-source-at-settle-time.md","filePath":"adr/0047-the-pull-request-state-judgment-reads-the-source-at-settle-time.md"}'),o={name:"adr/0047-the-pull-request-state-judgment-reads-the-source-at-settle-time.md"};function n(h,e,d,l,i,u){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0047-the-pull-request-state-judgment-reads-the-source-at-settle-time" tabindex="-1">ADR 0047: The pull request state judgment reads the source at settle time <a class="header-anchor" href="#adr-0047-the-pull-request-state-judgment-reads-the-source-at-settle-time" aria-label="Permalink to &quot;ADR 0047: The pull request state judgment reads the source at settle time&quot;">​</a></h1><p>Status: accepted Date: 2026-09-22</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>A transition branch tests a Judgment (ADR 0027): the review score against the configured threshold, and whether the linked pull request is still open. The score judgment reads live: when a review turn settles, the plane reads the pull request&#39;s comments through the command runner, and the judgment decides on what the source says at that moment.</p><p>The pull request state judgment did not. It decided from the ticket&#39;s projection: the membership&#39;s last refresh read the pull request&#39;s state, and the fire took it. That projection is the last refresh&#39;s fact, and the GitHub search index behind the pull request source still lists a merged pull request as open for a while after the merge lands. A turn that merged the pull request settles inside that window: the refresh at the fire&#39;s settle still reads the pull request open, the <code>pull-request-open</code> branch holds, the fire writes <code>needs-work</code> onto a merged pull request, and the machine derives the rework position from the labels it wrote. The Decision screen builds its offer from the fire&#39;s recorded outcome, so it offers the handoff of a task no state offers: rework on a pull request that is already merged. This is the recorded failure of issue #152 on the operator&#39;s own install: a merged pull request still wearing <code>needs-work</code>, and a Decision screen offering the rework handoff beside it.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>When a branch tests it, the pull request state is read straight from the source at the fire&#39;s settle.</strong> The fire issues one REST read of the pull request&#39;s own record through the command runner, with the source&#39;s host and the resolved auth, the way the score read issues the comment read. The record answers the judgment: a merged pull request, or one whose state is closed, is not open; one whose state is open is open. The read runs only when a branch of the transition tests the <code>pull-request-open</code> or <code>pull-request-closed</code> judgment, the same gate the score read keeps for the score judgment.</p><p><strong>A read that fails, or answers without a state the judgment reads, falls back to the projection&#39;s fact.</strong> The fire then decides on the last refresh, the way it did before the read existed: the judgment still decides, and the plane never blocks a settle on a source read it can answer another way. The score read keeps its own path: the two judgments read from different places in the source, the score from the pull request&#39;s comments, the open state from its record, and each read belongs to its own judgment.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>A merge that lands while the turn settles routes nowhere: no judgment holds, the fallback branch fires, the write converges the machine&#39;s labels off the merged pull request, the position derives to the parking state, and the cycle closes in auto mode or waits in manual mode with no handoff to offer.</li><li>A blocked merge still moves the pull request to rework: the read answers open, the <code>pull-request-open</code> branch holds, and the machine writes <code>needs-work</code> as before.</li><li>A state-judgment transition&#39;s fire gains one read, gated like the score read: no branch that tests the state, no read. The fail-open fallback keeps the old behavior for a source that cannot be read at that moment.</li><li>The Glossary&#39;s Judgment entry stands and is sharpened: the judgment is a fact read from the source at settle time, with the projection&#39;s last refresh as the read&#39;s fallback, never a stored verdict.</li></ul>',10)])])}const p=t(o,[["render",n]]);export{m as __pageData,p as default};
